<template>
  <TabbedWorkspaceCard class="node-registry-workspace" data-testid="node-registry-mirror-workspace">
    <template #meta><div class="registry-meta"><span class="registry-meta-note">实时读取节点 <code>registries.yaml</code>，保存后会重启对应节点的 K3s 服务<span v-if="nodes.length"> · {{ sameConfig ? '所有节点配置一致' : '节点配置存在差异' }}</span></span></div></template>
    <template #actions><div class="workspace-actions"><button class="icon-button" type="button" title="刷新节点配置" aria-label="刷新节点配置" :disabled="loading" @click="load"><RefreshCw :size="15" :class="{ 'is-spinning': loading }" /></button><button v-if="importableNodes.length" class="btn" type="button" :disabled="loading || saving" @click="openImport">导入代理镜像源</button><button v-if="nodes.length && sameConfig" class="btn btn-primary" type="button" :disabled="loading || saving" @click="openEditAll">编辑全部节点</button></div></template>
    <FeedbackBanner v-if="error" class="node-registry-error" tone="warning" :message="error" />
    <EmptyState v-if="loading && !loaded" variant="loading" message="正在读取节点镜像源配置..." />
    <EmptyState v-else-if="loaded && !nodes.length" message="当前集群没有可读取的节点配置" />
    <div v-else class="table-wrap"><table class="data-table node-registry-table"><thead><tr><th>节点</th><th>镜像源数量</th><th>配置 MD5</th><th>状态</th><th class="action-cell">操作</th></tr></thead><tbody><tr v-for="node in nodes" :key="node.server_id"><td class="node-cell"><span class="cell-primary">{{ node.name }}</span></td><td><span class="mirror-count">{{ node.actual?.length || 0 }}</span></td><td><code class="config-md5">{{ node.config_md5 || '-' }}</code></td><td><span class="badge" :class="nodeStateClass(displayState(node))" :title="node.state === 'drifted' && displayState(node) === 'matching' ? '节点之间配置一致，但与平台保存的期望规则不同' : undefined">{{ nodeStateLabel(displayState(node)) }}</span></td><td class="action-cell"><div class="row-actions"><button class="btn btn-sm" type="button" :disabled="saving" @click="openView(node)">查看配置</button><button class="btn btn-sm" type="button" :disabled="saving || node.state === 'unreachable'" @click="openEditNode(node)">编辑</button><button class="btn btn-sm btn-primary" type="button" :disabled="saving || node.state === 'unreachable'" @click="openSync(node)">同步到其他节点</button></div></td></tr></tbody></table></div>
  </TabbedWorkspaceCard>

  <BaseModal :open="importOpen" :teleport="true" overlay-class="node-registry-modal-overlay" dialog-class="node-registry-import-modal" title="导入代理镜像源" @close="closeImport">
    <div class="import-fields">
      <div class="form-group"><label class="form-label" for="import-proxy">Registry Proxy</label><SelectMenu id="import-proxy" v-model="importProxyID" aria-label="Registry Proxy" :disabled="importLoading" @change="loadImportRelays"><option value="" disabled>选择代理</option><option v-for="proxy in availableProxies" :key="proxy.id" :value="String(proxy.id)">{{ proxy.name }} · {{ proxy.registry }}</option></SelectMenu></div>
      <div class="form-group"><label class="form-label" for="import-endpoint">镜像地址</label><SelectMenu id="import-endpoint" v-model="importEndpoint" aria-label="镜像地址" :disabled="importLoading || importRelayLoading || !importProxyID"><option value="" disabled>选择地址</option><option v-for="option in importEndpointOptions" :key="option.value" :value="option.value">{{ option.label }}</option></SelectMenu></div>
      <div class="form-group"><label class="form-label" for="import-target">目标节点</label><SelectMenu id="import-target" v-model="importTargetID" aria-label="目标节点"><option value="" disabled>选择节点</option><option v-if="canImportAll" value="all">全部节点（配置一致）</option><option v-for="node in importableNodes" :key="node.server_id" :value="String(node.server_id)">{{ node.name }}</option></SelectMenu></div>
    </div>
    <p v-if="importLoading || importRelayLoading" class="modal-help">正在读取代理入口...</p>
    <p v-else-if="!availableProxies.length" class="modal-help">当前集群没有就绪的 Registry Proxy。</p>
    <p v-else class="modal-help">选择需要导入的地址和目标节点，下一步确认本次变更。</p>
    <FeedbackBanner v-if="importError" tone="warning" :message="importError" />
    <template #actions><button class="btn" type="button" @click="closeImport">取消</button><button class="btn btn-primary" type="button" :disabled="importLoading || importRelayLoading || !importProxyID || !importEndpoint || !importTargetID" @click="reviewImport">预览变更</button></template>
  </BaseModal>

  <BaseModal :open="Boolean(importReview)" :teleport="true" overlay-class="node-registry-modal-overlay" dialog-class="node-registry-import-modal" title="确认导入代理镜像源" @close="closeImportReview">
    <dl class="import-review-list">
      <div><dt>Registry</dt><dd>{{ importReview?.registry }}</dd></div>
      <div><dt>目标节点</dt><dd>{{ importReview?.targets.map(node => node.name).join('、') }}</dd></div>
      <div><dt>当前地址</dt><dd class="import-review-address">{{ importReview?.previousEndpoints.join('、') || '未配置' }}</dd></div>
      <div><dt>导入地址</dt><dd class="import-review-address">{{ importReview?.endpoint }}</dd></div>
    </dl>
    <p class="modal-help">仅替换此 Registry 的镜像地址，其他配置及现有认证保持不变。应用后将重启所选节点的 K3s 服务。</p>
    <FeedbackBanner v-if="importError" tone="warning" :message="importError" />
    <template #actions><button class="btn" type="button" :disabled="saving" @click="backToImport">返回选择</button><button class="btn btn-primary" type="button" :disabled="saving" @click="saveImport">{{ saving ? '应用并重启中...' : '应用并重启' }}</button></template>
  </BaseModal>

  <BaseModal :open="Boolean(viewTarget)" :teleport="true" overlay-class="node-registry-modal-overlay" dialog-class="node-registry-modal" size="large" title="查看节点镜像源配置" @close="closeView"><p class="modal-help">{{ viewTarget?.name }} 当前实时读取到的 registries.yaml 配置，密码不会展示。</p><div v-if="viewTarget?.actual?.length" class="config-view-list"><div class="config-view-header"><span>Registry</span><span>镜像地址</span><span>认证</span></div><div v-for="config in viewTarget.actual" :key="config.registry" class="config-view-row"><strong class="config-view-value config-view-registry" :title="config.registry">{{ config.registry }}</strong><span class="config-view-value config-view-endpoints" :title="config.endpoints.join('、')">{{ config.endpoints.join('、') || '未配置地址' }}</span><div class="config-view-flags"><span v-if="config.auth_configured" class="badge badge-online">{{ config.auth_username ? `账号：${config.auth_username}` : '已配置认证' }}</span><span v-if="config.insecure_skip_verify" class="badge badge-warning">跳过证书校验</span><span v-if="!config.auth_configured && !config.insecure_skip_verify" class="cell-secondary">-</span></div></div></div><EmptyState v-else message="当前节点未配置镜像源" /></BaseModal>

  <BaseModal :open="Boolean(editTarget)" :teleport="true" overlay-class="node-registry-modal-overlay" dialog-class="node-registry-modal" :title="editAll ? '编辑全部节点镜像源' : `编辑 ${editTarget?.name || ''} 镜像源`" size="large" @close="closeEdit"><p class="modal-help">可编辑 Registry、镜像地址和账号认证；密码或 Token 留空会保留节点现有凭据。{{ editAll ? '当前所有节点 MD5 一致，将同时修改全部节点。' : '' }}</p><div class="config-editor-list"><div class="config-editor-header"><span>Registry</span><span>镜像地址</span><span>账号（可选）</span><span>密码或 Token</span><span>操作</span></div><div v-for="(config, index) in editConfigs" :key="index" class="config-editor-row"><label class="form-group"><span class="sr-only">Registry</span><input v-model.trim="config.registry" class="form-input" required placeholder="docker.io" aria-label="Registry" /></label><label class="form-group endpoint-group"><span class="sr-only">镜像地址</span><textarea v-model="config.endpointText" class="form-input endpoint-input" required placeholder="https://mirror.example.com" aria-label="镜像地址" /></label><label class="form-group"><span class="sr-only">账号（可选）</span><input v-model.trim="config.authUsername" class="form-input" autocomplete="username" placeholder="留空则保留现有账号" aria-label="账号（可选）" /></label><label class="form-group"><span class="sr-only">密码或 Token</span><input v-model="config.authCredential" class="form-input" type="password" autocomplete="new-password" placeholder="留空则保留现有凭据" aria-label="密码或 Token" /></label><button v-if="editConfigs.length > 1" class="icon-button remove-config" type="button" title="移除镜像源" aria-label="移除镜像源" @click="removeConfig(index)">×</button></div></div><button class="btn btn-sm" type="button" @click="addConfig">+ 添加镜像源</button><FeedbackBanner v-if="actionError" tone="warning" :message="actionError" /><template #actions><button class="btn" type="button" :disabled="saving" @click="closeEdit">取消</button><button class="btn btn-primary" type="button" :disabled="saving" @click="saveConfig">{{ saving ? '保存并重启中...' : '保存并重启' }}</button></template></BaseModal>

  <BaseModal :open="Boolean(syncTarget)" :teleport="true" overlay-class="node-registry-modal-overlay" dialog-class="node-registry-modal" title="同步节点镜像源配置" @close="closeSync"><p class="modal-help">将“{{ syncTarget?.name }}”当前的完整 registries.yaml 复制到选中的节点，并重启目标节点 K3s 服务。认证信息也会一并保留。</p><div class="sync-node-list"><label v-for="node in syncCandidates" :key="node.server_id" class="sync-node-option"><input v-model="syncServerIDs" type="checkbox" :value="node.server_id" /><span><strong>{{ node.name }}</strong><small>{{ serverMeta(node.server_id) }} · MD5 {{ node.config_md5 || '-' }}</small></span></label></div><FeedbackBanner v-if="actionError" tone="warning" :message="actionError" /><template #actions><button class="btn" type="button" :disabled="saving" @click="closeSync">取消</button><button class="btn btn-primary" type="button" :disabled="saving || !syncServerIDs.length" @click="syncConfig">{{ saving ? '同步并重启中...' : '开始同步' }}</button></template></BaseModal>
</template>

<script setup>
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import { RefreshCw } from 'lucide-vue-next'
import { getServers } from '../../api/servers.js'
import { inspectActualNodeRegistryConfiguration, syncNodeRegistryConfiguration, updateNodeRegistryConfiguration } from '../../api/node-registry-mirrors.js'
import { getRegistryProxies, getRegistryProxyRelays } from '../../api/registry-proxies.js'
import BaseModal from '../../components/BaseModal.vue'
import EmptyState from '../../components/EmptyState.vue'
import FeedbackBanner from '../../components/FeedbackBanner.vue'
import SelectMenu from '../../components/SelectMenu.vue'
import TabbedWorkspaceCard from '../../components/TabbedWorkspaceCard.vue'

const props = defineProps({ clusterId: { type: [String, Number], default: '' } })
const servers = ref([]); const inspection = ref(null); const loaded = ref(false); const loading = ref(false); const saving = ref(false); const error = ref(''); const actionError = ref(''); const viewTarget = ref(null); const editTarget = ref(null); const editAll = ref(false); const editConfigs = ref([]); const syncTarget = ref(null); const syncServerIDs = ref([]); let refreshTimer
const importOpen = ref(false); const importLoading = ref(false); const importRelayLoading = ref(false); const importError = ref(''); const importProxies = ref([]); const importRelays = ref([]); const importProxyID = ref(''); const importEndpoint = ref(''); const importTargetID = ref(''); const importReview = ref(null)
const clusterServerIDs = computed(() => new Set(servers.value.filter(server => Number(server.cluster_id) === Number(props.clusterId) && server.cluster_role).map(server => Number(server.id))))
const nodes = computed(() => (inspection.value?.nodes || []).filter(node => !props.clusterId || clusterServerIDs.value.has(Number(node.server_id))))
const sameConfig = computed(() => nodes.value.length > 0 && nodes.value.every(node => node.config_md5) && new Set(nodes.value.map(node => node.config_md5)).size === 1)
const syncCandidates = computed(() => nodes.value.filter(node => node.server_id !== syncTarget.value?.server_id))
const importableNodes = computed(() => nodes.value.filter(node => !['unreachable', 'invalid', 'unsupported'].includes(node.state)))
const canImportAll = computed(() => sameConfig.value && importableNodes.value.length === nodes.value.length)
const availableProxies = computed(() => importProxies.value.filter(proxy => Number(proxy.cluster_id) === Number(props.clusterId) && proxy.status === 'ready'))
const selectedImportProxy = computed(() => availableProxies.value.find(proxy => String(proxy.id) === importProxyID.value))
const importEndpointOptions = computed(() => {
  const proxy = selectedImportProxy.value
  if (!proxy) return []
  return [...importRelays.value.filter(relay => relay.status === 'ready').map(relay => ({ value: `http://${relay.listen_ip}:${relay.listen_port}`, label: `中转 · ${relay.listen_ip}:${relay.listen_port}` })), { value: `http://${proxy.endpoint_host}:${proxy.node_port}`, label: `直达 · ${proxy.endpoint_host}:${proxy.node_port}` }]
})

async function load() { loading.value = true; error.value = ''; try { const [serverList, current] = await Promise.all([getServers(), inspectActualNodeRegistryConfiguration(props.clusterId ? { cluster_id: Number(props.clusterId) } : undefined)]); servers.value = serverList || []; inspection.value = current || { nodes: [] } } catch (err) { error.value = err.message || '读取节点镜像源配置失败' } finally { loaded.value = true; loading.value = false } }
function scheduleRefresh() { clearTimeout(refreshTimer); refreshTimer = setTimeout(async () => { await load(); scheduleRefresh() }, 15000) }
function serverMeta(id) { const server = servers.value.find(item => Number(item.id) === Number(id)); return server ? `${server.cluster_role === 'control-plane' ? '控制平面' : '工作节点'} · ${server.host}` : `节点 #${id}` }
function nodeStateLabel(state) { return { matching: '一致', missing: '缺失', drifted: '有差异', unsupported: '不支持', unreachable: '不可达', invalid: '配置无效' }[state] || '未知' }
function nodeStateClass(state) { return { matching: 'badge-online', missing: 'badge-danger', drifted: 'badge-warning', unsupported: 'badge-offline', unreachable: 'badge-danger', invalid: 'badge-danger' }[state] || 'badge-offline' }
function displayState(node) { if (['unreachable', 'unsupported', 'invalid', 'missing'].includes(node.state)) return node.state; return sameConfig.value && node.config_md5 ? 'matching' : node.state }
function openView(node) { viewTarget.value = node }
function closeView() { viewTarget.value = null }
function normalizeConfigs(configs) { return (configs || []).map(config => ({ registry: config.registry || '', endpointText: (config.endpoints || []).join('\n'), authUsername: config.auth_username || '', authCredential: '', insecure_skip_verify: Boolean(config.insecure_skip_verify) })) }
async function openImport() { importOpen.value = true; importError.value = ''; importLoading.value = true; importProxies.value = []; importProxyID.value = ''; importEndpoint.value = ''; importTargetID.value = canImportAll.value ? 'all' : String(importableNodes.value[0]?.server_id || ''); try { importProxies.value = await getRegistryProxies() || []; const first = availableProxies.value[0]; if (first) { importProxyID.value = String(first.id); await loadImportRelays(importProxyID.value) } } catch (err) { importError.value = err.message || '读取 Registry Proxy 失败' } finally { importLoading.value = false } }
function closeImport() { importOpen.value = false; importError.value = ''; importRelays.value = [] }
async function loadImportRelays(proxyID) { importRelayLoading.value = true; importError.value = ''; importRelays.value = []; importEndpoint.value = ''; try { const relays = await getRegistryProxyRelays(proxyID); if (importProxyID.value !== String(proxyID)) return; importRelays.value = relays || []; importEndpoint.value = importEndpointOptions.value[0]?.value || '' } catch (err) { if (importProxyID.value === String(proxyID)) importError.value = err.message || '读取中转入口失败' } finally { if (importProxyID.value === String(proxyID)) importRelayLoading.value = false } }
function reviewImport() { const proxy = selectedImportProxy.value; const all = importTargetID.value === 'all' && canImportAll.value; const targets = all ? nodes.value : importableNodes.value.filter(node => String(node.server_id) === importTargetID.value); if (!proxy || !targets.length || !importEndpointOptions.value.some(option => option.value === importEndpoint.value)) return; const previous = (targets[0].actual || []).find(config => config.registry.toLowerCase() === proxy.registry.toLowerCase()); importReview.value = { registry: proxy.registry, endpoint: importEndpoint.value, targets: targets.map(node => ({ server_id: node.server_id, name: node.name })), previousEndpoints: previous?.endpoints || [], configs: (targets[0].actual || []).map(config => ({ registry: config.registry, endpoints: [...config.endpoints], auth_username: config.auth_username || '', insecure_skip_verify: Boolean(config.insecure_skip_verify) })) }; importError.value = ''; importOpen.value = false }
function closeImportReview() { if (!saving.value) { importReview.value = null; importError.value = '' } }
function backToImport() { if (saving.value) return; importReview.value = null; importError.value = ''; importOpen.value = true }
async function saveImport() { if (!importReview.value || saving.value) return; saving.value = true; importError.value = ''; try { const review = importReview.value; const configs = review.configs.map(config => ({ ...config, auth_credential: '' })); const existing = configs.find(config => config.registry.toLowerCase() === review.registry.toLowerCase()); if (existing) existing.endpoints = [review.endpoint]; else configs.push({ registry: review.registry, endpoints: [review.endpoint], auth_username: '', auth_credential: '', insecure_skip_verify: false }); const result = await updateNodeRegistryConfiguration({ cluster_id: Number(props.clusterId), server_ids: review.targets.map(node => node.server_id), configs }); const failures = (result?.results || []).filter(item => item.status !== 'success'); if (failures.length) throw new Error(failures.map(item => `${review.targets.find(node => Number(node.server_id) === Number(item.server_id))?.name || `节点 #${item.server_id}`}：${item.detail || '应用失败'}`).join('；')); importReview.value = null; await load() } catch (err) { importError.value = err.message || '导入代理镜像源失败' } finally { saving.value = false } }
function openEditAll() { actionError.value = ''; editAll.value = true; editTarget.value = { name: '全部节点' }; editConfigs.value = normalizeConfigs(nodes.value[0]?.actual); if (!editConfigs.value.length) editConfigs.value = [{ registry: '', endpointText: '', authUsername: '', authCredential: '', insecure_skip_verify: false }] }
function openEditNode(node) { actionError.value = ''; editAll.value = false; editTarget.value = node; editConfigs.value = normalizeConfigs(node.actual); if (!editConfigs.value.length) editConfigs.value = [{ registry: '', endpointText: '', authUsername: '', authCredential: '', insecure_skip_verify: false }] }
function resetEdit() { editTarget.value = null; editConfigs.value = []; editAll.value = false; actionError.value = '' }
function closeEdit() { if (!saving.value) resetEdit() }
function addConfig() { editConfigs.value.push({ registry: '', endpointText: '', authUsername: '', authCredential: '', insecure_skip_verify: false }) }
function removeConfig(index) { editConfigs.value.splice(index, 1) }
async function saveConfig() { saving.value = true; actionError.value = ''; try { const configs = editConfigs.value.map(config => ({ registry: config.registry.trim(), endpoints: config.endpointText.split(/[\n,]+/).map(value => value.trim()).filter(Boolean), auth_username: config.authUsername.trim(), auth_credential: config.authCredential, insecure_skip_verify: config.insecure_skip_verify, auth_configured: Boolean(config.authUsername.trim() || config.authCredential) })).filter(config => config.registry && config.endpoints.length); if (!configs.length) throw new Error('至少配置一个镜像源'); const serverIDs = editAll.value ? nodes.value.map(node => node.server_id) : [editTarget.value.server_id]; const result = await updateNodeRegistryConfiguration({ cluster_id: Number(props.clusterId), server_ids: serverIDs, configs }); const failures = (result?.results || []).filter(item => item.status !== 'success'); if (failures.length) throw new Error(failures.map(item => `${nodes.value.find(node => node.server_id === item.server_id)?.name || `节点 #${item.server_id}`}：${item.detail || '保存失败'}`).join('；')); resetEdit(); await load() } catch (err) { actionError.value = err.message || '编辑节点镜像源失败' } finally { saving.value = false } }
function openSync(node) { actionError.value = ''; syncTarget.value = node; syncServerIDs.value = [] }
function closeSync() { if (saving.value) return; syncTarget.value = null; syncServerIDs.value = []; actionError.value = '' }
async function syncConfig() { saving.value = true; actionError.value = ''; try { await syncNodeRegistryConfiguration({ cluster_id: Number(props.clusterId), source_server_id: syncTarget.value.server_id, target_server_ids: syncServerIDs.value }); closeSync(); await load() } catch (err) { actionError.value = err.message || '同步节点镜像源失败' } finally { saving.value = false } }
onMounted(async () => { await load(); scheduleRefresh() }); onBeforeUnmount(() => clearTimeout(refreshTimer))
</script>

<style scoped>
.workspace-actions,.row-actions{display:flex;align-items:center;gap:8px}.registry-meta{min-width:0}.registry-meta-note{color:var(--text-muted);font-size:11px;line-height:1.4}.registry-meta-note code{color:var(--text-secondary)}.node-registry-error{margin:0 var(--space-20) var(--space-12)}.node-registry-table{min-width:980px}.node-registry-table td{vertical-align:middle}.node-registry-table th.action-cell,.node-registry-table td.action-cell{text-align:right}.node-registry-table .cell-primary{font-size:12px;font-weight:400}.node-registry-table tbody tr{height:42px}.node-cell{vertical-align:middle!important}.mirror-count{color:var(--text-primary);font-size:12px;font-weight:400}.config-md5{color:var(--text-secondary);font-size:12px;white-space:nowrap}.cell-secondary{display:block;color:var(--text-muted);font-size:11px}.modal-help{margin:0 0 14px;color:var(--text-secondary);font-size:13px;line-height:1.5}:global(.node-registry-modal-overlay){z-index:2000;align-items:flex-start;overflow-y:auto;padding:76px 16px 24px}:global(.node-registry-modal){max-height:calc(100dvh - 100px)}.config-view-list{display:grid;gap:0;max-height:52vh;overflow-y:auto}.config-view-row{display:grid;grid-template-columns:minmax(140px,.8fr) minmax(260px,1.5fr) auto;gap:12px;align-items:center;padding:12px 0;border-bottom:1px solid var(--border-muted)}.config-view-row>div{display:grid;gap:4px;min-width:0}.config-view-row>span:nth-child(2){overflow-wrap:anywhere;color:var(--text-secondary)}.config-editor-list{display:grid;gap:0;max-height:52vh;overflow-y:auto;margin-bottom:12px}.config-editor-row{display:grid;grid-template-columns:minmax(150px,.8fr) minmax(240px,1.4fr) auto auto;align-items:center;gap:10px;padding:9px 0;border-bottom:1px solid var(--border-muted)}.form-group{display:grid;gap:5px;min-width:0;margin:0}.form-label{color:var(--text-secondary);font-size:11px;font-weight:600}.endpoint-input{height:38px;min-height:38px;resize:none;line-height:1.35}.check-row{display:flex;align-items:center;gap:6px;white-space:nowrap;color:var(--text-secondary);font-size:12px}.remove-config{width:30px;height:30px;color:var(--danger)}.sync-node-list{display:grid;gap:8px;max-height:320px;overflow:auto}.sync-node-option{display:flex;align-items:flex-start;gap:10px;padding:10px;border:1px solid var(--border-muted);border-radius:var(--radius-control);background:var(--surface-subtle);cursor:pointer}.sync-node-option span{display:grid;gap:4px;min-width:0}.sync-node-option small{color:var(--text-secondary);font-size:11px;overflow-wrap:anywhere}@media(max-width:760px){.config-view-row{grid-template-columns:1fr;gap:5px}.config-editor-row{grid-template-columns:1fr}.check-row{justify-self:start}.remove-config{justify-self:end}:global(.node-registry-modal-overlay){padding-top:64px}}
